const body = $input.first().json.body;
const avaliacaoUrl = body?.avaliacaoUrl || 'https://g.page/r/CfugOJBgujYPEBM/review';
if (!body || body.evento !== 'avaliacao_google' || body.versao !== 1 ||
    !/^avaliacao-google-v1:[^/]+$/.test(body.idempotencyKey || '')) {
  throw new Error('Pedido de avaliacao invalido.');
}
if (typeof body.email !== 'string' || body.email.length > 120 ||
    !/^[^\s@,;<>]+@[^\s@,;<>]+\.[^\s@,;<>]+$/.test(body.email)) {
  throw new Error('Destinatario invalido.');
}
if (typeof avaliacaoUrl !== 'string' || !/^https:\/\/[^\s]+$/.test(avaliacaoUrl)) {
  throw new Error('Link de avaliacao invalido.');
}
const confirmadoEm = Date.parse(body.confirmadoEm);
if (!Number.isFinite(confirmadoEm) || confirmadoEm > Date.now() + 5 * 60 * 1000 ||
    typeof body.dataAtendimento !== 'string' || !/^\d{4}-\d{2}-\d{2}$/.test(body.dataAtendimento)) {
  throw new Error('Data do atendimento ou da confirmacao invalida.');
}
const nome = typeof body.nome === 'string' ? body.nome.trim().slice(0, 120) : '';
const escaparHtml = (valor) => String(valor).replace(/[&<>"']/g, (caractere) => ({
  '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;'
})[caractere]);
const nomeSeguro = escaparHtml(nome);
const linkSeguro = escaparHtml(avaliacaoUrl);
const saudacao = nomeSeguro ? 'Olá, ' + nomeSeguro + '!' : 'Olá!';
const assunto = 'Sua opinião sobre o atendimento de RG em Itanhandu';
const mensagem = (nome ? 'Olá, ' + nome + '!' : 'Olá!') +
  '\n\nVocê fez seu RG (Carteira de Identidade) na Câmara Municipal de Itanhandu.' +
  '\n\nGostaríamos de saber como foi seu atendimento. Se desejar, avalie nossa página no Google:' +
  '\n' + avaliacaoUrl +
  '\n\nSua participação é voluntária e nos ajuda a melhorar o atendimento. Este é um convite único.' +
  '\n\nCâmara Municipal de Itanhandu';
const mensagemHtml = [
  '<!doctype html>',
  '<html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">',
  '<meta name="color-scheme" content="light"><meta name="supported-color-schemes" content="light">',
  '<title>' + escaparHtml(assunto) + '</title></head>',
  '<body style="margin:0;padding:0;background:#f0f4f8;color:#1e293b;font-family:Arial,Helvetica,sans-serif;">',
  '<div style="display:none;max-height:0;overflow:hidden;opacity:0;color:transparent;">Conte como foi seu atendimento no Posto de Identificação da Câmara de Itanhandu.</div>',
  '<table role="presentation" width="100%" cellspacing="0" cellpadding="0" border="0" style="width:100%;background:#f0f4f8;border-collapse:collapse;">',
  '<tr><td align="center" style="padding:28px 12px;">',
  '<table role="presentation" width="600" cellspacing="0" cellpadding="0" border="0" style="width:100%;max-width:600px;background:#ffffff;border:1px solid #dbe4ee;border-radius:18px;border-collapse:separate;overflow:hidden;box-shadow:0 12px 32px rgba(15,35,60,.10);">',
  '<tr><td align="center" bgcolor="#0056b3" style="padding:26px 24px 23px;background:#0056b3;background-image:linear-gradient(135deg,#0056b3 0%,#003d82 100%);">',
  '<a href="https://cin.itanhandu.cam.mg.gov.br/" target="_blank" style="text-decoration:none;">',
  '<img src="https://cin.itanhandu.cam.mg.gov.br/assets/header-logo.png" width="257" alt="Câmara Municipal de Itanhandu" style="display:block;width:257px;max-width:82%;height:auto;border:0;color:#ffffff;font-size:18px;font-weight:bold;line-height:1.3;text-align:center;">',
  '</a></td></tr>',
  '<tr><td height="5" bgcolor="#f59e0b" style="height:5px;font-size:0;line-height:0;background:#f59e0b;">&nbsp;</td></tr>',
  '<tr><td style="padding:38px 38px 32px;">',
  '<p style="margin:0 0 18px;font-size:17px;line-height:1.6;color:#334155;">' + saudacao + '</p>',
  '<h1 style="margin:0 0 16px;color:#003d82;font-size:28px;line-height:1.2;font-weight:800;letter-spacing:-.3px;">Como foi seu atendimento?</h1>',
  '<p style="margin:0 0 22px;font-size:16px;line-height:1.65;color:#475569;">Você fez seu RG (Carteira de Identidade) no Posto de Identificação da Câmara Municipal de Itanhandu. Sua experiência pode ajudar outras pessoas e também nos orientar a melhorar o atendimento.</p>',
  '<table role="presentation" width="100%" cellspacing="0" cellpadding="0" border="0" style="width:100%;border-collapse:separate;background:#eff6ff;border:1px solid #bfdbfe;border-radius:12px;">',
  '<tr><td style="padding:18px 20px;color:#003d82;font-size:15px;line-height:1.55;font-weight:700;text-align:center;">Se desejar, compartilhe sua opinião em nossa página no Google.</td></tr>',
  '</table>',
  '<table role="presentation" cellspacing="0" cellpadding="0" border="0" align="center" style="margin:28px auto 22px;border-collapse:separate;">',
  '<tr><td align="center" bgcolor="#0056b3" style="border-radius:10px;background:#0056b3;box-shadow:0 8px 18px rgba(0,86,179,.22);">',
  '<a href="' + linkSeguro + '" target="_blank" style="display:inline-block;padding:15px 26px;border:1px solid #0056b3;border-radius:10px;color:#ffffff;font-size:16px;line-height:1.2;font-weight:800;text-decoration:none;">Avaliar atendimento no Google</a>',
  '</td></tr></table>',
  '<p style="margin:0 0 8px;font-size:13px;line-height:1.55;color:#64748b;text-align:center;">Se o botão não abrir, copie e cole este endereço no navegador:</p>',
  '<p style="margin:0 0 26px;font-size:13px;line-height:1.55;text-align:center;word-break:break-all;"><a href="' + linkSeguro + '" target="_blank" style="color:#0056b3;text-decoration:underline;">' + linkSeguro + '</a></p>',
  '<table role="presentation" width="100%" cellspacing="0" cellpadding="0" border="0" style="width:100%;border-collapse:separate;background:#f8fafc;border-left:4px solid #f59e0b;border-radius:8px;">',
  '<tr><td style="padding:14px 16px;color:#566174;font-size:13px;line-height:1.55;">Sua participação é voluntária. Este é um convite único enviado após a confirmação do seu atendimento.</td></tr>',
  '</table>',
  '</td></tr>',
  '<tr><td bgcolor="#101a2b" style="padding:24px 30px;background:#101a2b;text-align:center;">',
  '<p style="margin:0 0 6px;color:#ffffff;font-size:14px;line-height:1.45;font-weight:700;">Posto de Identificação</p>',
  '<p style="margin:0 0 12px;color:#cbd5e1;font-size:12px;line-height:1.55;">Câmara Municipal de Itanhandu<br>Rua Eng. Paulo Franco da Rosa, 298 · Itanhandu/MG</p>',
  '<p style="margin:0;font-size:12px;line-height:1.5;"><a href="https://cin.itanhandu.cam.mg.gov.br/" target="_blank" style="color:#93c5fd;text-decoration:underline;">cin.itanhandu.cam.mg.gov.br</a></p>',
  '</td></tr>',
  '</table>',
  '</td></tr></table>',
  '</body></html>'
].join('');
return [{ json: {
  email: body.email,
  idempotencyKey: body.idempotencyKey,
  assunto,
  mensagem,
  mensagemHtml
} }];

const pedido = $('Preparar convite').first().json;
const resultado = $input.first().json;
if (!Array.isArray(resultado.accepted) ||
    !resultado.accepted.some(email => String(email).toLowerCase() === pedido.email.toLowerCase())) {
  throw new Error('O servidor SMTP nao confirmou a aceitacao do destinatario.');
}
return [{ json: { enviado: true, idempotencyKey: pedido.idempotencyKey } }];
